void gc_keys(struct list_head *keys) {
    struct list_head *pos, *tmp;
    key_ref_t key;

    list_for_each_safe(pos, tmp, keys) {
        struct key *key_ptr = list_entry(pos, struct key, list);

        if (key_ptr->usage > 0 && key_ptr->type != KEY_TYPE_NEGATIVE) {
            key_ptr->type->destroy(key_ptr);
            key_ptr->user->n_keys--;
            key_ptr->user->n_bytes -= key_ptr->payload_size;
        }

        list_del(pos);
        kfree(key_ptr->description);
        debug("Key %d destroyed", key_ptr->id);
        kfree(key_ptr);
    }
}

