void cleanup_keys(struct list_head *keys) {
    struct key *key, *tmp;

    list_for_each_entry_safe(key, tmp, keys, list) {
        if (key->type && !key->negative) {
            key->type->destroy(key);
        }

        user_key tracking = key->user;
        tracking->qnkeys--;
        tracking->qbytes -= key->datalen + sizeof(*key);

        list_del(&key->list);
        free(key->description);
        debug_key_free(key);
        kmem_cache_free(key_cache, key);
    }
}

void cleanup_keys(struct list_head *keys) {
    struct key *pos, *tmp;

    list_for_each_entry_safe(pos, tmp, keys, list) {
        if (pos->type->destroy && !pos->negative) {
            pos->type->destroy(pos);
        }

        if (pos->user) {
            atomic_dec(&pos->user->count);
            atomic_sub(pos->bytes, &pos->user->quota);
        }

        list_del(&pos->list);
        kfree(pos->description);
        debug_key_cleanup(pos);
        kmem_cache_free(key_cache, pos);
    }
}
